package cn.zhuatech.agenthub.controller; import cn.zhuatech.agenthub.common.ApiResponse; import cn.zhuatech.agenthub.dto.AgentHubDto.*; import cn.zhuatech.agenthub.service.AgentHubService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final AgentHubService service;public OperationsAdminController(AgentHubService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
